(() => {
  'use strict';
  const qs = (s, r = document) => r.querySelector(s);
  const qsa = (s, r = document) => Array.from(r.querySelectorAll(s));

  // ===== DOM anchors =====
  const startView = qs('#startView');
  const testView = qs('#testView');
  const resultView = qs('#resultView');
  const tabs = qsa('[data-step-btn]');
  const panes = qsa('[data-step-pane]');
  const btnPrev = qs('[data-disc-prev]');
  const btnNext = qs('[data-disc-next]');
  const btnFinish = qs('[data-disc-finish]');
  const progressEl = qs('#discProgress');
  const tabsScroller = qs('.disc-tabs');
  const scoreEl = qs('#discScore');
  const linkInput = qs('#discLink');
  const LAST_STEP = 7;
  let step = 0;

  const isMobileUI = () =>
    (window.matchMedia && window.matchMedia('(max-width: 767px)').matches) ||
    (window.matchMedia && window.matchMedia('(pointer: coarse)').matches && window.matchMedia('(max-width: 1024px)').matches);

  const centerActiveTab = () => {
    if (!isMobileUI() || !tabsScroller) return;
    const active = tabs.find((t) => Number(t.dataset.stepBtn) === step);
    if (!active) return;
    active.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
  };

  const render = () => {
    tabs.forEach((t) => {
      const is = Number(t.dataset.stepBtn) === step;
      t.classList.toggle('is-active', is);
      t.setAttribute('aria-selected', is ? 'true' : 'false');
    });
    panes.forEach((p) => p.classList.toggle('is-active', Number(p.dataset.stepPane) === step));
    if (btnPrev) btnPrev.disabled = step === 0;
    if (btnNext) btnNext.hidden = step === LAST_STEP;
    if (btnFinish) btnFinish.hidden = step !== LAST_STEP;
    if (progressEl) progressEl.style.width = (((step + 1) / 8) * 100) + '%';
    requestAnimationFrame(centerActiveTab);
  };

  const setStep = (n) => { step = Math.max(0, Math.min(LAST_STEP, n)); render(); };

  const show = (el) => {
    [startView, testView, resultView].forEach((v) => { if (v) v.hidden = (v !== el); });
    window.scrollTo({ top: 0, left: 0 });
  };
