    clone.style.top = (e.clientY - drag.offY) + 'px';

    // live reordering: midpoint rule (as in the original)
    const sibs = Array.from(list.children).filter((n) => n.tagName === 'LI' && n !== li);
    for (const sib of sibs) {
      const r = sib.getBoundingClientRect();
      const before = (e.clientY - r.top) < r.height / 2;
      const sibAfter = !!(li.compareDocumentPosition(sib) & Node.DOCUMENT_POSITION_FOLLOWING);
      if (before && sibAfter) list.insertBefore(li, sib);
      else if (!before && !sibAfter) list.insertBefore(li, sib.nextSibling);
    }

    // auto scroll near the edges of the scroller
    const sc = qs('.disc-panes');
    if (sc && sc.scrollHeight > sc.clientHeight + 2) {
      const r = sc.getBoundingClientRect();
      if (e.clientY < r.top + 48) sc.scrollTop -= 10;
      else if (e.clientY > r.bottom - 48) sc.scrollTop += 10;
    }
  };

  const finishDrag = () => {
    if (drag) {
      drag.clone.remove();
      drag.li.classList.remove('is-dragging');
      drag = null;
    }
    pending = null;
    document.body.classList.remove('is-dragging');
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup', onUp);
    window.removeEventListener('pointercancel', onCancel);
  };
  const onUp = () => finishDrag();
  const onCancel = () => finishDrag();

  const panesRoot = qs('#rootwizard');
  panesRoot.addEventListener('pointerdown', (e) => {
    if (drag || pending) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const li = e.target.closest ? e.target.closest('.disc-item') : null;
    if (!li) return;
    const pane = li.closest('.disc-pane');
    if (!pane || !pane.classList.contains('is-active')) return;
    if (dragByHandle) {
      const h = e.target.closest('.disc-handle');
      if (!h || h.parentElement !== li) return;
    }
    pending = { li, x: e.clientX, y: e.clientY };
    window.addEventListener('pointermove', onMove, { passive: false });
    window.addEventListener('pointerup', onUp, { passive: false });
    window.addEventListener('pointercancel', onCancel, { passive: false });
  });
  // Safety: don't leave a stale drag state if the pointer leaves the window
  document.addEventListener('pointerout', ...) // not needed; pointercancel/up will handle it.
```

