  document.addEventListener('click', async (e) => {
    const btn = e.target.closest ? e.target.closest('[data-copy]') : null;
    if (!btn) return;
    const input = qs(btn.getAttribute('data-copy'));
    if (!input) return;
    if (btn.dataset.copyBusy === '1') return;
    btn.dataset.copyBusy = '1';
    const text = input.value || '';
    let ok = false;
    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
      try { await navigator.clipboard.writeText(text); ok = true; } catch (_) { /* ignore */ }
    }
    if (!ok) {
      input.focus();
      input.select();
      try { ok = document.execCommand('copy'); } catch (_) { ok = false; }
      input.blur();
    }
    if (ok) setCopyState(btn, true);
    window.setTimeout(() => { setCopyState(btn, false); btn.dataset.copyBusy = '0'; }, 1500);
  });
