```js
const beginDrag = (e) => {
  const li = pending.li;
  const rect = li.getBoundingClientRect();
  const clone = li.cloneNode(true);
  clone.classList.remove('is-dragging');
  clone.classList.add('disc-item--ghost');
  clone.style.position = 'fixed';
  clone.style.left = rect.left + 'px';
  clone.style.top = rect.top + 'px';
  clone.style.width = rect.width + 'px';
  clone.style.minWidth = rect.width + 'px';
  clone.style.height = rect.height + 'px';
  clone.style.margin = '0';
  clone.style.zIndex = '60';
  clone.style.pointerEvents = 'none';
  document.body.appendChild(clone);
  li.classList.add('is-dragging');
  document.body.classList.add('is-dragging');
  drag = { li, clone, list: li.closest('.disc-list'), offX: e.clientX - rect.left, offY: e.clientY - rect.top };
  pending = null;
  moveClone(e);
};
```

onPointerMove:
```js
const onPointerMove = (e) => {
  if (pending) {
    const dx = e.clientX - pending.x, dy = e.clientY - pending.y;
    if (dx*dx + dy*dy < 36) return; // 6px threshold
    beginDrag(e);
  }
  if (!drag) return;
  e.preventDefault();
  moveClone(e);
  reposition(e);
  edgeScroll(e);
};
```

moveClone: set left/top = client - off.

reposition: midpoint rule against sibling elements (as in the original):
```js
const sibs = Array.from(drag.list.children).filter(n => n.tagName === 'LI' && n !== drag.li);
for (const sib of sibs) {
  const r = sib.getBoundingClientRect();
  const before = (e.clientY - r.top) < r.height / 2;
  const sibAfter = drag.li.compareDocumentPosition(sib) & Node.DOCUMENT_POSITION_FOLLOWING;
  if (before && sibAfter) drag.list.insertBefore(drag.li, sib);
  else if (!before && !sibAfter) drag.list.insertBefore(drag.li, sib.nextSibling);
}
```

edgeScroll:
```js
const scroller = document.querySelector('.disc-panes');
if (scroller && scroller.scrollHeight > scroller.clientHeight + 4) {
  const r = scroller.getBoundingClientRect();
  const zone = 48, step = 14;
  if (e.clientY < r.top + zone) scroller.scrollTop -= step;
  else if (e.clientY > r.bottom - zone) scroller.scrollTop += step;
}
```

onPointerEnd:
```js
const onPointerEnd = () => {
  detachDragListeners();
  if (drag) {
    drag.clone.remove();
    drag.li.classList.remove('is-dragging');
    drag = null;
  }
  pending = null;
  document.body.classList.remove('is-dragging');
};
```

