    if (!btn || btn.dataset.copyBusy === '1') return;
    const input = document.querySelector(btn.getAttribute('data-copy'));
    if (!input) return;
    btn.dataset.copyBusy = '1';
    const text = input.value || '';
    let ok = false;
    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
      try { await navigator.clipboard.writeText(text); ok = true; } catch (_err) { /* fallback below */ }
    }
    if (!ok) {
      input.focus();
      input.select();
      try { ok = document.execCommand('copy'); } catch (_err) { ok = false; }
      input.blur();
    }
    if (ok) copyState(btn, true);
    window.setTimeout(() => { copyState(btn, false); btn.dataset.copyBusy = '0'; }, 1500);
  });
