Drag and drop:
```js
  const dragByHandle = typeof window.matchMedia === 'function' && window.matchMedia('(pointer: coarse)').matches;
  document.body.classList.add(dragByHandle ? 'drag-mode-handle' : 'drag-mode-any');

  let pending = null;
  let drag = null;

  const addDragListeners = () => {
    window.addEventListener('pointermove', onPointerMove, { passive: false });
    window.addEventListener('pointerup', onPointerEnd, { passive: false });
    window.addEventListener('pointercancel', onPointerEnd, { passive: false });
  };
  const removeDragListeners = () => {
    window.removeEventListener('pointermove', onPointerMove);
    window.removeEventListener('pointerup', onPointerEnd);
    window.removeEventListener('pointercancel', onPointerEnd);
  };

  const beginDrag = (e) => {
    const li = pending.li;
    const rect = li.getBoundingClientRect();
    const clone = li.cloneNode(true);
    clone.classList.remove('is-dragging');
    clone.classList.add('disc-item--ghost');
    clone.style.position = 'fixed';
    clone.style.left = rect.left + 'px';
    clone.style.top = rect.top + 'px';
    clone.style.width = rect.width + 'px';
    clone.style.minWidth = rect.width + 'px';
    clone.style.maxWidth = rect.width + 'px';
    clone.style.height = rect.height + 'px';
    clone.style.margin = '0';
    clone.style.zIndex = '80';
    clone.style.pointerEvents = 'none';
    document.body.appendChild(clone);
    li.classList.add('is-dragging');
    document.body.classList.add('is-dragging');
    drag = { li, clone, list: li.closest('.disc-list'), offX: e.clientX - rect.left, offY: e.clientY - rect.top };
    pending = null;
  };

  const moveDrag = (e) => {
    if (pending) {
      const dx = e.clientX - pending.x;
      const dy = e.clientY - pending.y;
      if (dx * dx + dy * dy < 36) return; // 6px threshold
      beginDrag(e);
    }
    if (!drag) return;
    e.preventDefault();
    drag.clone.style.left = e.clientX - drag.offX + 'px';
    drag.clone.style.top = e.clientY - drag.offY + 'px';

    const sibs = Array.from(drag.list.children).filter((n) => n.tagName === 'LI' && n !== drag.li);
    for (const sib of sibs) {
      const r = sib.getBoundingClientRect();
      const before = e.clientY - r.top < r.height / 2;
      const sibAfter = !!(drag.li.compareDocumentPosition(sib) & Node.DOCUMENT_POSITION_FOLLOWING);
      if (before && sibAfter) drag.list.insertBefore(drag.li, sib);
      else if (!before && !sibAfter) drag.list.insertBefore(drag.li, sib.nextSibling);
    }

    const scroller = panesEl;
    if (scroller.scrollHeight > scroller.clientHeight + 4) {
      const r = scroller.getBoundingClientRect();
      const zone = 48;
      const stepPx = 14;
      if (e.clientY < r.top + zone) scroller.scrollTop -= stepPx;
      else if (e.clientY > r.bottom - zone) scroller.scrollTop += stepPx;
    }
  };

  const endDrag = () => {
    if (drag) {
      drag.clone.remove();
      drag.li.classList.remove('is-dragging');
      drag = null;
    }
    pending = null;
    document.body.classList.remove('is-dragging');
  };

  const onPointerMove = (e) => { moveDrag(e); };
  const onPointerEnd = () => { removeDragListeners(); endDrag(); };

  panesEl.addEventListener('pointerdown', (e) => {
    if (drag || pending) return;
    const li = e.target && e.target.closest ? e.target.closest('.disc-item') : null;
    if (!li) return;
    const pane = li.closest('.disc-pane');
    if (!pane || !pane.classList.contains('is-active')) return;
    if (dragByHandle) {
      const handle = e.target.closest('.disc-handle');
      if (!handle || handle.parentNode !== li) return;
    } else if (e.pointerType === 'mouse' && e.button !== 0) {
      return;
    }
    pending = { li, x: e.clientX, y: e.clientY };
    addDragListeners();
  });

  // Keyboard reorder (accessibility)
  panesEl.addEventListener('keydown', (e) => {
    const li = e.target && e.target.closest ? e.target.closest('.disc-item') : null;
    if (!li) return;
    if (e.key === 'ArrowUp' && li.previousElementSibling) {
      e.preventDefault();
      li.parentNode.insertBefore(li, li.previousElementSibling);
      li.focus();
    } else if (e.key === 'ArrowDown' && li.nextElementSibling) {
      e.preventDefault();
      li.parentNode.insertBefore(li.nextElementSibling, li);
      li.focus();
    }
  });

  render();
  showOnly(startView);
})();
